/* 拾忆 · Recall Coach 展示站：单一样式表，无构建步骤，无外部字体与外链资源。 */
:root {
  --ink: #10202c;
  --ink-soft: #3f5464;
  --muted: #6a7f8d;
  --paper: #f7f8f6;
  --card: #ffffff;
