/* 拾忆 · Recall Coach 展示站：单一样式表，无构建步骤，无外部字体与外链资源。 */
:root {
  --ink: #10202c;
  --ink-soft: #3f5464;
  --muted: #6a7f8d;
  --paper: #f7f8f6;
  --card: #ffffff;
  --line: #e0e5e6;
  --brand: #0f766e;
  --brand-soft: #e3f2f0;
  --amber: #b45309;
  --radius: 14px;
  --shadow: 0 1px 2px rgba(16, 32, 44, .05), 0 12px 30px -18px rgba(16, 32, 44, .25);
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 16px/1.7 "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Source Han Sans SC", "Noto Sans CJK SC", system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}

code, pre { font-family: var(--mono); font-size: .88em; }
code { background: #eef2f1; border-radius: 4px; padding: .1em .35em; color: #14403a; }
a { color: var(--brand); }

.wrap { width: min(1160px, calc(100% - 40px)); margin: 0 auto; }

/* ---------------- 顶栏 ---------------- */
.topbar {
  position: sticky; top: 0; z-index: 40;
  background: rgba(16, 32, 44, .96);
  color: #eaf3f1;
  border-bottom: 1px solid rgba(255, 255, 255, .08);
  backdrop-filter: blur(6px);
}
.topbar-inner { display: flex; align-items: center; gap: 20px; height: 62px; }
.brand { display: flex; align-items: baseline; gap: 8px; text-decoration: none; color: inherit; }
.brand-mark { font-size: 20px; font-weight: 700; letter-spacing: .06em; }
.brand-sub { font-size: 12px; letter-spacing: .18em; text-transform: uppercase; color: #93b3ad; }
.nav { margin-left: auto; display: flex; gap: 4px; flex-wrap: wrap; }
.nav a {
  color: #cfe1dd; text-decoration: none; font-size: 14px;
  padding: 6px 10px; border-radius: 8px;
}
.nav a:hover { background: rgba(255, 255, 255, .1); color: #fff; }
.nav a[aria-current="true"] { background: var(--brand); color: #fff; }
.topbar-actions { display: flex; gap: 8px; }

/* ---------------- 按钮 ---------------- */
.btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 9px 16px; border-radius: 10px; border: 1px solid transparent;
  font-size: 14px; font-weight: 600; text-decoration: none; cursor: pointer;
  transition: transform .12s ease, background .12s ease, border-color .12s ease;
}
.btn:active { transform: translateY(1px); }
.btn.primary { background: var(--brand); color: #fff; }
.btn.primary:hover { background: #0c655e; }
.btn.line { background: #fff; color: var(--ink); border-color: var(--line); }
.btn.line:hover { border-color: var(--brand); color: var(--brand); }
.btn.ghost { background: rgba(255, 255, 255, .08); color: #eaf3f1; border-color: rgba(255, 255, 255, .18); }
.btn.ghost:hover { background: rgba(255, 255, 255, .16); color: #fff; }

expect(page.locator("#ranking-after table tr").count() - 1 == 8, "展示更新后的 8 个知识点优先级")
shot(page, out_dir / "03-diagnose-result.png")
report["screenshots"].append("03-diagnose-result.png")

# 重复提交保护：按钮锁定之外，服务端必须拒绝二次累计（直接绕过页面按钮提交）
expect("已判分" in page.inner_text("#submit"), f"提交后按钮显示已完成状态：{page.inner_text('#submit')}")
expect(page.locator("#submit").is_disabled(), "已完成判分的会话不允许再次点击提交")
replay_probe = page.evaluate(
    """async () => {
      const learner = CTX.learner.learner_id;
      const session = CTX.session.session_id;
      const count = async () => (await (await fetch(`/api/learners/${learner}`)).json()).memory_entry_count;
      const before = await count();
      const response = await fetch(`/api/learners/${learner}/sessions/${session}/submit`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ answers: [{ question_id: "probe-only", chosen: "A" }] }),
      });
      const data = await response.json();
      const after = await count();
      return {
        status: response.status,
        before: before,
        after: after,
        replay: !!(data.replay && data.replay.repeated_submit),
        newMemories: data.replay ? data.replay.new_memories_this_request : null,
        keptChoice: data.results ? data.results[0].chosen : null,
      };
    }"""
)
expect(replay_probe["status"] == 200 and replay_probe["replay"] is True, f"绕过按钮重复提交被识别为回放：{replay_probe}")
expect(replay_probe["before"] == replay_probe["after"], f"重复提交改变了记忆条数：{replay_probe}")
expect(replay_probe["newMemories"] == 0, f"重复提交又写入了记忆：{replay_probe}")
expect(replay_probe["keptChoice"] is not None, "回放返回的是当时留存的作答与判分")

# 再来一轮：应切换为记忆驱动复习（等待新会话安排真正替换页面内容）
previous_title = page.inner_text("#plan-title")
page.click("#next-round")
page.wait_for_function(
    "(title) => document.querySelector('#plan-title').textContent !== title"
    " && document.querySelector('#learner-state').textContent.includes('本次安排已写入记忆')",
    arg=previous_title,
    timeout=30000,
)
mode = page.inner_text("#plan-mode")

