    b = pw.chromium.launch(executable_path=ex) if ex else pw.chromium.launch()
    p = b.new_context(viewport={"width":1440,"height":950}).new_page()
    p.goto("http://127.0.0.1:4173/", wait_until="load")
    print(p.evaluate("""() => {
      const out = {};
      const sel = ['.hero', '.hero-grid', '.hero-copy', '.hero-copy h1', '.hero-facts', '.hero-shot', '.hero-shot img'];
      for (const s of sel) {
        const el = document.querySelector(s);
        if (!el) { out[s] = 'MISSING'; continue; }
        const r = el.getBoundingClientRect(); const cs = getComputedStyle(el);
        out[s] = {rect: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)],
                  display: cs.display, visibility: cs.visibility, opacity: cs.opacity, color: cs.color,
                  fontSize: cs.fontSize, text: (el.innerText||'').slice(0,24), gridCols: cs.gridTemplateColumns};
      }
      out['.hero-grid computed'] = getComputedStyle(document.querySelector('.hero-grid')).cssText.slice(0,0) || getComputedStyle(document.querySelector('.hero-grid')).display;
      out['sheets'] = document.styleSheets.length;
      out['cssRules'] = Array.from(document.styleSheets).map(s => { try { return s.cssRules.length } catch(e){ return 'ERR:'+e.message } });
      return out;
    }""", ))
    b.close()
